/**
 * The subscription is the authority on the plan. The column on the
 * organization is only a cache, and it can lag (or disagree already), so
 * every read reports the subscription's plan when a row exists and the
 * cached plan otherwise.
 */
async function withAuthoritativePlan(org: Organization): Promise<Organization> {
  const subscription = await findSubscription(org.id);
  if (!subscription || subscription.plan === org.plan) return org;
  return { ...org, plan: subscription.plan };
}

export async function findOrgById(orgId: OrgId): Promise<Organization | null> {
  const row = getDb()
    .select()
    .from(organizations)
    .where(eq(organizations.id, orgId))
    .get();
  return row ? withAuthoritativePlan(toOrganization(row)) : null;
}

