input.new_string:
type BucketState = { tokens: number; updatedAt: number; capacity: number };

const buckets = new Map<string, BucketState>();

/**
 * Fallback plan for an org whose row cannot be read. A live subscription
 * (or the workspace column, when there is no subscription) replaces it.
 */
const planByOrg = new Map<OrgId, PlanId>();

/** Records an org's plan so subsequent bucket sizes scale with its quota. */
export function setOrgPlan(orgId: OrgId, plan: PlanId): void {
  planByOrg.set(orgId, plan);
}

/** True when a connection is already open or a database file is on disk. */
async function planStoreReady(): Promise<boolean> {
  const configured = process.env.TASKFLOW_DB_PATH;
  if (configured === ":memory:") return true;
  if (configured && existsSync(configured)) return true;
  if (!configured && existsSync("./data/taskflow.db")) return true;

  const { hasOpenDb } = await import("@/server/db/client");
  return hasOpenDb();
}

/**
 * Subscription plan, else the plan cached on the workspace, else the
 * recorded fallback. One org's plan never supplies another's ceiling.
 */
async function planForLimit(orgId: OrgId): Promise<PlanId> {
  const recorded = planByOrg.get(orgId);
  if (!(await planStoreReady())) return recorded ?? "free";

  try {
    const { findOrgById } = await import(
      "@/server/repositories/organization-repository"
    );
    const org = await findOrgById(orgId);
    if (org) return org.plan;
  } catch {
    // The bucket still has to answer when the schema is not there yet.
  }

  return recorded ?? "free";
}

