export async function consumeRateLimit(
  orgId: OrgId,
  bucketKey: string,
  cost = 1,
): Promise<RateLimitVerdict> {
  const config = configFor(orgId, bucketKey);
  const key = `${orgId}:${bucketKey}`;
  const nowMs = Date.now();

  const state = buckets.get(key) ?? { tokens: config.capacity, updatedAt: nowMs };
  const elapsedMinutes = (nowMs - state.updatedAt) / 60_000;
  const tokens = Math.min(
    config.capacity,
    state.tokens + elapsedMinutes * config.refillPerMinute,
  );

  const allowed = tokens >= cost;
  const remaining = allowed ? tokens - cost : tokens;
  buckets.set(key, { tokens: remaining, updatedAt: nowMs });

input.new_string:
export async function consumeRateLimit(
  orgId: OrgId,
  bucketKey: string,
  cost = 1,
): Promise<RateLimitVerdict> {
  const config = configFor(await planForLimit(orgId), bucketKey);
  const key = `${orgId}:${bucketKey}`;
  const nowMs = Date.now();

  const state = buckets.get(key) ?? {
    tokens: config.capacity,
    updatedAt: nowMs,
    capacity: config.capacity,
  };

  // A plan change resizes the bucket in place. Tokens already spent stay
  // spent, and the new ceiling applies to the next request of this org only.
  let tokens = state.tokens;
  if (state.capacity !== config.capacity) {
    const spent = Math.max(0, state.capacity - state.tokens);
    tokens = Math.max(0, config.capacity - spent);
  }

  const elapsedMinutes = (nowMs - state.updatedAt) / 60_000;
  tokens = Math.min(
    config.capacity,
    tokens + elapsedMinutes * config.refillPerMinute,
  );

  const allowed = tokens >= cost;
  const remaining = allowed ? tokens - cost : tokens;
  buckets.set(key, { tokens: remaining, updatedAt: nowMs, capacity: config.capacity });

