async function withAuthoritativePlan(org: Organization): Promise<Organization> {
  let subscription: Awaited<ReturnType<typeof findSubscription>>;
  try {
    subscription = await findSubscription(org.id);
  } catch (error) {
    // A database that has not created the subscriptions table yet has no
    // subscription to defer to; the workspace column stays in force.
    if (error instanceof Error && /no such table/i.test(error.message)) {
      return org;
    }
    throw error;
  }
  if (!subscription || subscription.plan === org.plan) return org;
  return { ...org, plan: subscription.plan };
}

  return Promise.all(
    rows.map((row) => withAuthoritativePlan(toOrganization(row.org))),
  );
}

