import { eq } from "drizzle-orm";
import { isEnabled } from "@/lib/feature-flags";
import { consumeRateLimit, resetRateLimits } from "@/lib/rate-limit";
import { getDb, organizations, subscriptions } from "@/server/db";
import { runTrialExpiryJob } from "@/server/jobs/trial-expiry-job";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { changePlan } from "@/server/services/billing-service";
import { createComment } from "@/server/services/comment-service";
import { buildFlagContext } from "@/server/services/feature-flag-service";
import { inviteMember } from "@/server/services/invitation-service";
import { createIssue } from "@/server/services/issue-service";
import { createProject } from "@/server/services/project-service";
import { createWebhook } from "@/server/services/webhook-service";
import { toIsoTimestamp } from "@/types/common";
import { createTenant, useTemporaryDatabase } from "./tests/server/_support/fixtures";

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}

const cleanup = await useTemporaryDatabase();

try {
  // Report 1: subscription says growth, organization column still says free.
  const drifted = await createTenant("drifted", "free");
  getDb()
    .update(subscriptions)
    .set({ plan: "growth", status: "active" })
    .where(eq(subscriptions.orgId, drifted.org.id))
    .run();

  const shown = await orgRepo.findOrgById(drifted.org.id);
  assert(shown?.plan === "growth", `switcher plan was ${shown?.plan}`);

  const flags = buildFlagContext(drifted.actors.owner, shown);
  assert(isEnabled("csv_export", flags), "csv export still gated on the stale free plan");
  assert(isEnabled("webhooks", flags), "webhooks flag did not follow growth");

  await createProject(drifted.actors.owner, {
    orgId: drifted.org.id,
    name: "Second",
    slug: "second",
    key: "SEC",
    description: null,
    visibility: "org",
    leadId: null,
    color: "#6366f1",
    targetDate: null,
  });
  await createProject(drifted.actors.owner, {
    orgId: drifted.org.id,
    name: "Third",
    slug: "third",
    key: "THR",
    description: null,
    visibility: "org",
    leadId: null,
    color: "#6366f1",
    targetDate: null,
  });

  await inviteMember(drifted.actors.owner, {
    orgId: drifted.org.id,
    email: "sixth@drifted.test",
    role: "member",
  });

  resetRateLimits();
  const issue = await createIssue(drifted.actors.member, {
    orgId: drifted.org.id,
    projectId: drifted.project.id,
    title: "Burst",
    description: null,
    status: "backlog",
    priority: "none",
    assigneeId: null,
    parentId: null,
    estimate: null,
    dueAt: null,
    labelIds: [],
  });
  for (let i = 0; i < 61; i += 1) {
    await createComment(drifted.actors.member, {
      orgId: drifted.org.id,
      issueId: issue.id,
      body: `comment ${i}`,
      parentId: null,
      mentionedUserIds: [],
    });
  }

  // Mirror downgrade: subscription starter, column still growth. No webhooks.
  getDb()
    .update(organizations)
    .set({ plan: "growth" })
    .where(eq(organizations.id, drifted.org.id))
    .run();
  getDb()
    .update(subscriptions)
    .set({ plan: "starter", status: "active" })
    .where(eq(subscriptions.orgId, drifted.org.id))
    .run();
  const starterOrg = await orgRepo.findOrgById(drifted.org.id);
  assert(starterOrg?.plan === "starter", `downgrade shown as ${starterOrg?.plan}`);
  let webhookError = "";
  try {
    await createWebhook(drifted.actors.owner, {
      orgId: drifted.org.id,
      url: "https://example.test/hook",
      eventTypes: ["issue.created"],
    });
  } catch (error) {
    webhookError = error instanceof Error ? error.message : String(error);
  }
  assert(/not included/i.test(webhookError), `webhook create did not refuse: ${webhookError}`);

  // Report 2: trial already swept to free on the subscription, column still growth.
  const expired = await createTenant("expired-trial", "growth");
  getDb()
    .update(subscriptions)
    .set({ plan: "free", status: "active" })
    .where(eq(subscriptions.orgId, expired.org.id))
    .run();
  const expiredOrg = await orgRepo.findOrgById(expired.org.id);
  assert(expiredOrg?.plan === "free", `expired workspace still ${expiredOrg?.plan}`);
  let third = "";
  try {
    await createProject(expired.actors.owner, {
      orgId: expired.org.id,
      name: "Second",
      slug: "second",
      key: "SEC",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });
    await createProject(expired.actors.owner, {
      orgId: expired.org.id,
      name: "Third",
      slug: "third",
      key: "THR",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });
  } catch (error) {
    third = error instanceof Error ? error.message : String(error);
  }
  assert(/project/i.test(third), `third project was not refused: ${third}`);
  assert(!isEnabled("webhooks", buildFlagContext(expired.actors.owner, expiredOrg)), "growth features survived");

  // Report 3: choosing a plan ends the trial. A still-trialing org is moved.
  const chosen = await createTenant("chosen", "growth");
  await changePlan(chosen.actors.owner, {
    orgId: chosen.org.id,
    plan: "growth",
    interval: "monthly",
  });
  const past = "2020-01-01T00:00:00.000Z";
  getDb()
    .update(subscriptions)
    .set({ currentPeriodEnd: past })
    .where(eq(subscriptions.orgId, chosen.org.id))
    .run();

  const stillTrial = await createTenant("still-trial", "growth");
  getDb()
    .update(subscriptions)
    .set({ currentPeriodEnd: past })
    .where(eq(subscriptions.orgId, stillTrial.org.id))
    .run();

  const overgrown = await createTenant("overgrown", "growth");
  getDb()
    .update(subscriptions)
    .set({ currentPeriodEnd: past })
    .where(eq(subscriptions.orgId, overgrown.org.id))
    .run();
  await usageRepo.incrementUsage(overgrown.org.id, { seatsUsed: 10, projectsUsed: 5 });

  const untouched = await createTenant("untouched", "starter");

  const now = new Date("2026-06-01T00:00:00.000Z");
  await runTrialExpiryJob(now);

  const chosenSub = await subscriptionRepo.findSubscription(chosen.org.id);
  const trialSub = await subscriptionRepo.findSubscription(stillTrial.org.id);
  const overSub = await subscriptionRepo.findSubscription(overgrown.org.id);
  const otherSub = await subscriptionRepo.findSubscription(untouched.org.id);
  assert(chosenSub?.plan === "growth" && chosenSub.status === "active", `chosen plan became ${chosenSub?.plan}/${chosenSub?.status}`);
  assert(trialSub?.plan === "free", `expired trial stayed ${trialSub?.plan}`);
  assert((await orgRepo.findOrgById(stillTrial.org.id))?.plan === "free", "org column did not follow the sweep");
  assert(overSub?.plan === "growth", `over-limit trial moved to ${overSub?.plan}`);
  assert(otherSub?.plan === "starter", `other workspace moved to ${otherSub?.plan}`);

  const beforeSecond = {
    chosen: chosenSub?.plan,
    trial: trialSub?.plan,
    over: overSub?.plan,
    other: otherSub?.plan,
  };
  await runTrialExpiryJob(now);
  assert((await subscriptionRepo.findSubscription(chosen.org.id))?.plan === beforeSecond.chosen, "second sweep moved a chosen plan");
  assert((await subscriptionRepo.findSubscription(stillTrial.org.id))?.plan === beforeSecond.trial, "second sweep moved free again");
  assert((await subscriptionRepo.findSubscription(overgrown.org.id))?.plan === beforeSecond.over, "second sweep moved an over-limit trial");
  assert((await subscriptionRepo.findSubscription(untouched.org.id))?.plan === beforeSecond.other, "second sweep moved another workspace");

  // A refused downgrade changes nothing.
  const rich = await createTenant("rich", "growth");
  await usageRepo.incrementUsage(rich.org.id, { seatsUsed: 10 });
  let refused = "";
  try {
    await changePlan(rich.actors.owner, {
      orgId: rich.org.id,
